// Parity test: the JS port must reproduce the legacy Python reference verifier (rule mode)
// on 137 documents / 1228 citations (fixtures generated by tools/gen_golden.py).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { verify } from '../src/core/index.js';

const docs = fs.readFileSync(new URL('./fixtures/golden.jsonl', import.meta.url), 'utf8')
  .split('\n').filter(Boolean).map(l => JSON.parse(l));

test('golden parity: citations, laws, verdicts and quote scores match the reference', () => {
  let total = 0, same = 0; const diffs = [];
  for (const d of docs) {
    const got = verify(d.text, { asOf: d.as_of, legacy: true });
    const n = Math.max(got.length, d.results.length);
    for (let i = 0; i < n; i++) {
      total++;
      const e = d.results[i], g = got[i];
      const ok = e && g && e.citation === g.citation && e.type === g.type && (e.article ?? null) === (g.article ?? null)
        && (e.clause ?? null) === (g.clause ?? null) && (e.law ?? null) === (g.law ?? null)
        && (e.law_hint ?? null) === (g.law_hint ?? null) && e.verdict === g.verdict
        && (e.quote_score == null ? g.quote_score == null : Math.abs(e.quote_score - g.quote_score) <= 0.001);
      if (ok) same++; else if (diffs.length < 15) diffs.push({ id: d.id, i, expected: e, got: g && { citation: g.citation, law: g.law, law_hint: g.law_hint, article: g.article, clause: g.clause, verdict: g.verdict, quote_score: g.quote_score } });
    }
  }
  const rate = same / total;
  if (rate < 1) console.error(JSON.stringify(diffs, null, 1));
  console.log(`golden parity ${same}/${total} = ${(rate * 100).toFixed(2)}%`);
  assert.ok(rate >= 0.99, `parity ${(rate * 100).toFixed(2)}% < 99%`);
});
